"""Eight original aggressive B- and T/NK-lymphoma questions."""
from create_hodgkin import rows,q,HL,NV
from qbank_authoring import ref
LB=ref('EHA: Large B-Cell Lymphoma Guideline, 2025','https://pmc.ncbi.nlm.nih.gov/articles/PMC12456099/')
AB=ref('NCI: Aggressive B-Cell Lymphoma Treatment','https://www.cancer.gov/types/lymphoma/hp/aggressive-b-cell-lymphoma-treatment-pdq')
MC=ref('NCI: Mantle Cell Lymphoma Treatment','https://www.cancer.gov/types/lymphoma/hp/mantle-cell-lymphoma-treatment')
TK=ref('ESMO/EHA: Peripheral T- and NK-Cell Lymphoma Guideline, 2025','https://www.annalsofoncology.org/article/S0923-7534%2825%2900059-6/fulltext')
q('A rapidly enlarging nodal mass contains sheets of large CD20-positive lymphoid cells. What is an important leading diagnosis?', 'Diffuse large B-cell lymphoma',[
 ('CLL/SLL','That is usually composed of small mature lymphocytes with a different pattern.'),('Classical Hodgkin lymphoma','The typical malignant-cell distribution and phenotype differ.'),('T-lymphoblastic lymphoma','It has precursor T-lineage features rather than a mature large-B-cell pattern.')],
 'Large-cell morphology and lineage define the initial category', '**DLBCL is common but biologically heterogeneous.**',['Additional immunophenotyping and genetics refine the diagnosis.','Exclude other defined large-B-cell entities.'], '**Obtain complete staging and risk assessment promptly.**',['LDH, performance status and extranodal sites contribute.','Curative-intent therapy is possible in many patients.'],[['Morphology','Large lymphoid cells'],['Lineage','Mature B-cell phenotype'],['Next step','Subtype, stage and risk']],[LB],style='clinical_scenario')
q('Which is a standard curative-intent treatment framework for many fit patients with DLBCL?', 'Anti-CD20–based combination systemic therapy, such as R-CHOP or eligible Pola-R-CHP according to risk and guidance',[
 ('Rituximab alone as sufficient for every aggressive case','Combination therapy is usually required.'),('Observation alone for every symptomatic high-burden case','This is not the usual aggressive-lymphoma approach.'),('ATRA/arsenic for all CD20-positive tumors','That is an APL-specific pathway.')],
 'Aggressive histology requires a disease- and risk-matched regimen', '**R-CHOP remains an important framework; Pola-R-CHP is an option in defined settings.**',['Histological subtype and IPI influence selection.','The R-CHP backbone omits vincristine when polatuzumab is included.'], '**Assess cardiac function, infection risks and fitness.**',['Anthracycline exposure and frailty can change the approach.','Stage alone does not determine whether cure is possible.'],[['Framework','Anti-CD20 combination treatment'],['Selection','Subtype, IPI and fitness'],['Preparation','Cardiac and infectious-risk assessment']],[LB])
q('What distinguishes a MYC/BCL2-rearranged large-B-cell lymphoma from a double-expressor lymphoma?', 'The rearranged category requires genetic rearrangement evidence; protein overexpression on IHC alone is not equivalent',[
 ('The two terms are fully interchangeable','Protein expression and gene rearrangement are distinct findings.'),('Any high Ki-67 proves both rearrangements','Proliferation rate does not establish the rearrangements.'),('A MYC protein stain replaces all genetic testing','Appropriate FISH or other validated testing is needed.')],
 'Use precise pathology language because it affects risk assessment', '**Double expression is an immunohistochemical description.**',['A rearranged entity is defined through genetics within the relevant classification.','WHO and ICC distinctions should be applied carefully.'], '**Do not infer the regimen from an imprecise label.**',['Obtain adequate tissue and the required tests.','Discuss high-risk disease within an expert lymphoma pathway.'],[['IHC','Protein expression'],['FISH / genetics','Rearrangements'],['Clinical use','Accurate subtype and risk']],[LB])
q('A rapidly growing abdominal lymphoma has a near-100% proliferative fraction, a starry-sky pattern and an IG::MYC rearrangement. Which diagnosis is most likely?', 'Burkitt lymphoma',[
 ('Follicular lymphoma with a typical indolent pattern','The biology and proliferation are much more aggressive.'),('CLL/SLL','This does not fit the high-grade morphology and MYC pattern.'),('Plasma-cell MGUS','That is not an aggressive nodal/abdominal lymphoma diagnosis.')],
 'Rapid turnover creates immediate metabolic risk', '**Burkitt lymphoma has a characteristic mature B-cell phenotype and MYC-associated biology.**',['The morphology and genetics must be integrated.','Not every MYC-rearranged lymphoma is Burkitt.'], '**Plan TLS prevention and an appropriate intensive disease-specific programme.**',['CNS assessment/protection is important.','Do not delay specialist management while a rapidly expanding mass progresses.'],[['Clues','Very high proliferation and starry sky'],['Genetics','IG::MYC'],['Urgency','Tumor lysis and rapid progression']],[AB],style='clinical_scenario')
q('A CD5-positive B-cell lymphoma is cyclin D1 positive with t(11;14). Which diagnosis is most likely?', 'Mantle cell lymphoma',[
 ('Typical CLL/SLL','It usually has a different CD23/CD200 and cyclin-D1 pattern.'),('Follicular lymphoma','It is generally a germinal-center phenotype with a different common translocation.'),('Classical Hodgkin lymphoma','It does not fit this mature B-cell genetic pattern.')],
 'CD5 expression does not uniquely identify CLL', '**CCND1-related cyclin D1 overexpression is characteristic of most MCL.**',['SOX11 can support assessment in selected cases.','There are atypical and cyclin-D1-negative cases requiring expert work-up.'], '**Assess the biological and clinical spectrum.**',['Some leukemic nonnodal cases are indolent.','TP53 and blastoid features can indicate higher risk.'],[['Marker','CD5 with cyclin D1'],['Typical rearrangement','t(11;14)'],['Diagnosis','Mantle cell lymphoma']],[MC],style='clinical_scenario')
q('A patient with aggressive B-cell lymphoma relapses early after first-line treatment. Which principle is most appropriate?', 'Prompt specialist reassessment including biopsy when indicated and evaluation for current cellular or salvage strategies',[
 ('Repeat the identical first-line regimen indefinitely without reassessment','Early failure requires a new strategy.'),('Assume all relapsed disease is untreatable','Several effective options exist for suitable patients.'),('Choose treatment solely from the old CT size','Histology, timing, fitness and prior therapy matter.')],
 'Relapse timing changes the treatment pathway', '**CAR-T therapy has an important role in selected primary refractory or early-relapsed large-B-cell lymphoma.**',['Other salvage and transplant strategies remain relevant in defined settings.','Biopsy can confirm relapse and exclude an alternative process.'], '**Assess the patient early enough to preserve options.**',['Cell collection, bridging and organ fitness may require planning.','Bispecific and other targeted options depend on the setting and local approval.'],[['Reassessment','Histology and relapse timing'],['Options','Current cellular / salvage pathways'],['Planning','Fitness and logistics']],[LB],style='clinical_scenario')
q('A destructive nasal lesion shows an EBV-associated cytotoxic NK/T-cell lymphoma phenotype. Which disease category is most likely?', 'Extranodal NK/T-cell lymphoma',[
 ('CLL/SLL','This is a mature B-cell disorder with a different distribution and biology.'),('Typical follicular lymphoma','It does not fit the destructive EBV-associated cytotoxic pattern.'),('Plasma-cell MGUS','This is not a localized destructive lymphomatous lesion category.')],
 'Site and viral biology can identify a distinct lymphoma pathway', '**EBV association and cytotoxic lineage are key features.**',['Confirm with adequate tissue and appropriate viral/phenotypic studies.','Necrosis can make superficial samples nondiagnostic.'], '**Use a disease-specific treatment strategy.**',['Radiation and non-anthracycline/asparaginase-containing approaches can be important depending on stage.','Do not assume generic B-cell R-CHOP applies to all lymphomas.'],[['Site','Often nasal / upper aerodigestive'],['Biology','EBV-associated NK/T phenotype'],['Treatment','Subtype-specific pathway']],[TK],style='clinical_scenario')
q('A patient with celiac disease develops weight loss, abdominal pain and an intestinal T-cell lymphoma. Which association is most characteristic?', 'Enteropathy-associated T-cell lymphoma',[
 ('Mantle cell lymphoma solely because the bowel is involved','The T-cell phenotype and celiac context suggest a different disease.'),('Classical Hodgkin lymphoma as the obligatory celiac malignancy','This is not the characteristic association.'),('B-ALL established by bowel symptoms alone','That requires a precursor B-cell phenotype.')],
 'The intestinal background can provide an etiological clue', '**EATL is associated with an enteropathy/celiac context.**',['Not every intestinal T-cell neoplasm is EATL.','Monomorphic epitheliotropic and other entities have distinct features.'], '**Assess complications and obtain expert pathology.**',['Perforation, obstruction and malnutrition can complicate care.','Coordinate systemic lymphoma treatment and nutritional support.'],[['Background','Celiac / enteropathy context'],['Lineage','T cell'],['Care','Histological distinction and complication management']],[TK],style='clinical_scenario')
